const FAQPage = () => {
  const faqs = [
    {
      question: "Why do cats purr?",
      answer: "While purring often indicates contentment, cats also purr to soothe themselves when they are stressed, injured, or even giving birth. It's a versatile communication tool and self-healing mechanism."
    },
    {
      question: "How much sleep do cats really need?",
      answer: "On average, cats sleep between 12 and 16 hours a day. They are crepuscular, meaning they are most active during dawn and dusk, saving their energy for these hunting hours."
    },
    {
      question: "Why do cats always land on their feet?",
      answer: "Cats have a 'righting reflex' thanks to their flexible spine and lack of a collarbone. This allows them to twist their bodies mid-air, though they can still be injured in falls from great heights."
    },
    {
      question: "Why do cats have whiskers?",
      answer: "Whiskers are highly sensitive tactile hairs called vibrissae. They are rooted deep in the skin and connected to the nervous system, helping cats navigate in the dark and detect subtle changes in air currents."
    },
    {
      question: "Can cats see in total darkness?",
      answer: "No, cats cannot see in complete darkness, but they only need about one-sixth of the light level humans do. Their eyes have a tapetum lucidum, which reflects light back through the retina to enhance night vision."
    }
  ];

  return (
    <div className="container">
      <header>
        <h1>Feline Frequently Asked Questions</h1>
        <p>Everything you ever wanted to know about our feline friends.</p>
      </header>
      <main>
        {faqs.map((faq, index) => (
          <FAQItem key={index} question={faq.question} answer={faq.answer} />
        ))}
      </main>
    </div>
  );
};

const App = () => {
  return <FAQPage />;
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
