        {faqs.map((faq, index) => (
          <FAQItem key={index} index={index} question={faq.question} answer={faq.answer} />
        ))}
      </main>
    </div>
  );
};

const App = () => {
  return <FAQPage />;
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
